from pathlib import Path
p=Path('/mnt/data/teddywork/index.html')
s=p.read_text()
s=s.replace('''        <!-- MIRROR — COMPLIMENTS -->\n        <button\n          class="hotspot mirror-hotspot"''','''        <!-- TEDDY — IMPORTANT DATES -->\n        <button\n          class="hotspot teddy-hotspot"\n          aria-label="Our important dates"\n        ></button>\n\n        <!-- MIRROR — COMPLIMENTS -->\n        <button\n          class="hotspot mirror-hotspot"''')
insert='''\n\n  <!-- TEDDY — IMPORTANT DATES -->\n  <div class="teddy-modal" id="teddyModal" aria-hidden="true">\n    <div class="teddy-backdrop"></div>\n    <div class="teddy-card" role="dialog" aria-modal="true" aria-labelledby="teddyTitle">\n      <button class="teddy-close" id="teddyClose" aria-label="Close">×</button>\n      <div class="teddy-header">\n        <div class="teddy-avatar">🧸</div>\n        <div>\n          <div class="teddy-kicker">THE DATES WE KEEP</div>\n          <h2 id="teddyTitle">Our Important Dates</h2>\n        </div>\n      </div>\n\n      <div class="teddy-days">\n        <div class="teddy-days-number" id="teddyDaysNumber">0</div>\n        <div class="teddy-days-label">DAYS TOGETHER</div>\n        <div class="teddy-days-sub" id="teddyDaysSub">And counting. ♡</div>\n      </div>\n\n      <div class="teddy-list" id="teddyList"></div>\n\n      <button class="teddy-add" id="teddyAdd">＋ Add Important Date</button>\n      <div class="teddy-form" id="teddyForm" hidden>\n        <div class="teddy-form-title">Add a date you never want to forget.</div>\n        <label>Emoji <input id="teddyEmoji" maxlength="4" value="❤️" placeholder="❤️"></label>\n        <label>Title <input id="teddyTitleInput" maxlength="80" placeholder="The day we started dating"></label>\n        <label>Date <input id="teddyDateInput" type="date"></label>\n        <label>Description <textarea id="teddyDescriptionInput" rows="2" maxlength="240" placeholder="A short description…"></textarea></label>\n        <label>Little memory <textarea id="teddyMemoryInput" rows="3" maxlength="500" placeholder="Something you want to remember about this day…"></textarea></label>\n        <div class="teddy-form-actions">\n          <button class="teddy-cancel" id="teddyCancel">Cancel</button>\n          <button class="teddy-save" id="teddySave">Save Date ♡</button>\n        </div>\n        <div class="teddy-status" id="teddyStatus"></div>\n      </div>\n    </div>\n  </div>\n'''
s=s.replace('''  <!-- MIRROR COMPLIMENTS -->''', insert+'''\n  <!-- MIRROR COMPLIMENTS -->''')
p.write_text(s)
